// 窄社会阶段在真实1000人输入上核全社会域；固定其他phase已分配的ID，仅证明本域而非整advance。
#include "resident/domains/social/social_model.hpp"
#include "resident/checkpoint/codec_visitor.hpp"
#include <fstream>
#include <iostream>
// 发布优化构建也必须执行本测试断言，不能让NDEBUG形成假绿。
#ifdef NDEBUG
#undef NDEBUG
#endif
#include <cassert>
using namespace hanmo::resident;
BoundaryValue read(const char* path){std::ifstream f(path);auto r=parse_boundary_json(std::string((std::istreambuf_iterator<char>(f)),{}));assert(r.ok);return std::move(r.value);}
// 本oracle首半日无活动战斗/会话；夹具明确核空，不能在生产把任意忙碌当空。
struct FirstPhaseActivity final:ActivityRead {bool in_open_battle(const StableId&)const override{return false;}bool in_interaction(const StableId&,const StableId&)const override{return false;}};
int main(int argc,char** argv){assert(argc==4);auto raw=read(argv[1]),before=read(argv[2]),after=read(argv[3]);assert(boundary::object(*before.find("battles"),"").empty());assert(boundary::object(*before.find("interactions"),"").empty());auto catalog=decode_common_catalog(*raw.find("data"));auto policies=decode_social_catalog(*raw.find("data"));assert(catalog.ok&&policies.ok);before.find("results")->data=BoundaryValue::Dict{};auto common=decode_common_seed(before,catalog.value);auto social=decode_social_seed(before);if(!common.ok){std::cerr<<common.error.original.code<<":"<<common.error.original.path<<"\n";return 1;}if(!social.ok){std::cerr<<social.error.original.code<<":"<<social.error.original.path<<"\n";return 1;}common.value.next_instance_id=675;CommonStore store(std::move(common.value),std::make_shared<const CommonCatalog>(catalog.value));FirstPhaseActivity activity;auto result=step_social(store,social.value,policies.value,catalog.value,activity,1);if(!result.ok){std::cerr<<result.error.original.code<<"\n";return 1;}auto out=encode_social_state(social.value);for(auto& row:std::get<BoundaryValue::Dict>(out.data)){auto diff=compare_boundary(*after.find(row.first),row.second);if(!diff.exact()){std::cerr<<row.first<<":"<<(diff.value_difference?diff.value_difference->path:diff.order_difference->path)<<":"<<(diff.value_difference?diff.value_difference->reason:diff.order_difference->reason)<<"\n";return 1;}}auto exported=encode_common_state(store.state());for(auto& row:std::get<BoundaryValue::Dict>(exported.find("inventories")->data))if(row.first.rfind("bag:actor.scale.",0)==0){auto diff=compare_boundary(*after.find("inventories")->find(row.first),row.second);assert(diff.values_equal);}store.state().identity.tick=1;assert(validate_social(store,social.value,catalog.value).ok);auto replay=step_social(store,social.value,policies.value,catalog.value,activity,1);assert(replay.ok&&!replay.value.applied);CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);assert(visit_social_checkpoint(writer,social.value).ok&&writer.finish().ok);SocialState restored;const auto& input=bytes;CodecVisitor reader(input);assert(visit_social_checkpoint(reader,restored).ok&&reader.finish().ok);assert(compare_boundary(encode_social_state(social.value),encode_social_state(restored)).exact());std::cout<<"state_social: PASS (1000-actor first social phase, "<<result.value.events.size()<<" exact events, all relations/memories/scale-bag values, replay, checkpoint)\n";}
